//! Public consumer: unchanged Source keys, generated bytes and errors; no parser internals.

mod common;

use common::{Fixture, files_under};
use onegit_git::{DiffOptions, DiffTarget, GitCommand, PartialPatch, Repository};
use serde_json::Value;
use std::fs;
use std::path::PathBuf;

#[test]
fn matches_every_actual_source_partial_patch_outcome() {
    let reference: Value =
        serde_json::from_str(include_str!("../fixtures/partial-patch.json")).unwrap();

    let mut selections = 0;

    for case in reference["cases"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let parsed = PartialPatch::new(case["patch"].as_str().unwrap());

        if let Some(error) = case["error"].as_str() {
            assert_eq!(parsed.unwrap_err().to_string(), error, "Source {name}");

            continue;
        }

        let parsed = parsed.unwrap();

        assert_eq!(
            serde_json::to_value(parsed.lines()).unwrap(),
            case["lines"],
            "Source {name}"
        );

        for selection in case["selections"].as_array().unwrap() {
            let lines: Vec<_> = selection["input"]
                .as_array()
                .unwrap()
                .iter()
                .map(|line| line.as_str().unwrap().to_owned())
                .collect();

            let actual = parsed.select(&lines);

            if let Some(error) = selection["error"].as_str() {
                assert_eq!(
                    actual.unwrap_err().to_string(),
                    error,
                    "Source {name}/{lines:?}"
                );
            } else {
                assert_eq!(
                    actual.unwrap(),
                    selection["value"].as_str().unwrap(),
                    "Source {name}/{lines:?}"
                );
            }

            selections += 1;
        }
    }

    assert_eq!(reference["cases"].as_array().unwrap().len(), 34);
    assert_eq!(selections, 36);
}

#[test]
fn generated_patches_apply_only_selected_lines_to_an_isolated_git_index() {
    for (name, original, working, selected_lines, expected) in [
        (
            "replacement",
            Some("start\nold\nmiddle\nend\n"),
            Some("start\nnew\nextra\nmiddle\nend\n"),
            vec!["+:3"],
            "start\nold\nextra\nmiddle\nend\n",
        ),
        (
            "new-file",
            None,
            Some("one\ntwo\n三🙂\n"),
            vec!["+:2"],
            "two\n",
        ),
        (
            "partial-deletion",
            Some("first\nlast"),
            None,
            vec!["-:1"],
            "last",
        ),
        (
            "no-final-newline",
            Some("start\nlast"),
            Some("start\n"),
            vec!["-:2"],
            "start\n",
        ),
    ] {
        let fixture = Fixture::new();

        fixture.write("excluded", "base excluded\n");

        if let Some(original) = original {
            fixture.write("file", original);
        }

        fixture.commit("base");
        fixture.write("excluded", "staged excluded\n");
        fixture.git_os(["add".into(), "--".into(), "excluded".into()]);
        fixture.write("excluded", "unstaged excluded\n");

        if let Some(working) = working {
            fixture.write("file", working);
        } else {
            fs::remove_file(fixture.root.join("file")).unwrap();
        }

        let index = fs::read(fixture.root.join(".git/index")).unwrap();
        let head = fixture.git(&["rev-parse", "HEAD"]);
        let staged = fixture.git(&["diff", "--cached", "--binary"]);
        let mut working_before = files_under(&fixture.root);

        working_before.retain(|path, _| !path.starts_with(".git"));
        let repository = Repository::open(&fixture.root, fixture.process(), None).unwrap();
        let paths = [PathBuf::from("file")];
        let mut options = DiffOptions::new(DiffTarget::Changes);

        options.paths = Some(&paths);
        let diff = repository.diff(options, None).unwrap();
        let parsed = PartialPatch::new(&diff.patch).unwrap();
        let selected_lines: Vec<_> = selected_lines.into_iter().map(str::to_owned).collect();
        let selected = parsed.select(&selected_lines).unwrap();
        let alternate = fixture.temporary.path().join("isolated-index");
        let process = fixture.process();
        let mut seed = GitCommand::new(&fixture.root, ["read-tree", "HEAD"]);

        seed.index_file = Some(&alternate);
        process.run(seed).unwrap();
        let mut apply = GitCommand::new(
            &fixture.root,
            ["apply", "--cached", "--whitespace=nowarn", "-"],
        );

        apply.index_file = Some(&alternate);
        apply.stdin = selected.as_bytes();
        process
            .run(apply)
            .unwrap_or_else(|error| panic!("{name}: {error}"));
        let mut inspect = GitCommand::new(&fixture.root, ["show", ":file"]);

        inspect.index_file = Some(&alternate);
        assert_eq!(
            process.run(inspect).unwrap().stdout,
            expected.as_bytes(),
            "{name}"
        );
        assert_eq!(
            fs::read(fixture.root.join(".git/index")).unwrap(),
            index,
            "{name}"
        );
        assert_eq!(fixture.git(&["rev-parse", "HEAD"]), head, "{name}");
        assert_eq!(
            fixture.git(&["diff", "--cached", "--binary"]),
            staged,
            "{name}"
        );
        assert_eq!(
            fs::read(fixture.root.join("excluded")).unwrap(),
            b"unstaged excluded\n",
            "{name}"
        );
        let mut working_after = files_under(&fixture.root);

        working_after.retain(|path, _| !path.starts_with(".git"));
        assert_eq!(working_after, working_before, "{name}");

        if let Some(working) = working {
            assert_eq!(
                fs::read(fixture.root.join("file")).unwrap(),
                working.as_bytes(),
                "{name}"
            );
        } else {
            assert!(!fixture.root.join("file").exists(), "{name}");
        }
    }
}
